INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_1_body', 'I was brought into an <strong>insolvent Devon business</strong> to help rescue it.<br /><br />
INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_1_label', '<strong>The starting point</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_2_body', 'I rebuilt the structure, restored financial control and stabilised the business.<br /><br />
INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_2_label', '<strong>What changed</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_3_body', 'The turnaround succeeded.<br /><br />
INSERT INTO content (section_key, content) VALUES ('casestudy__2.phase_3_label', '<strong>The outcome</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__2.subtext', 'The advice we give comes from businesses we have actually <strong>run, rebuilt and successfully exited.</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.heading', '<strong>The Insolvent Turnaround</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.label', '<strong>Evidence: 02</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_1_body', 'I took over an insolvent Devon firm with <strong>zero provision for VAT</strong> and unpaid staff. The business was technically dead on arrival. I stepped in as a Director and seized <strong>total financial control</strong>.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_1_label', '<strong>The Mess</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_2_body', 'I didn''t just advise.  I performed a structural overhaul. I <strong>ring-fenced the tax liabilities</strong>, paid down creditors on terms, and put the company back on a <strong>professional footing</strong>.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_2_label', '<strong>The Intervention</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_3_body', 'The business went from chaos to a <strong>marketable asset.</strong> I engineered a clean exit with a strong return for everyone involved.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.phase_3_label', '<strong>The Result</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__3.subtext', 'A sinking ship. <strong>High turnover masked a mess underneath.</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.heading', '<strong>The Insolvent Turnaround</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.label', '<strong>Evidence: 02</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_1_body', 'A Devon marine firm working on superyachts, including projects for Princess Yachts, asked Tom for help. There was no provision for VAT or tax, the bookkeeping was months behind, and the business was close to insolvency.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_1_label', '<strong>The Situation</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_2_body', 'Tom took full financial control, with the chequebook in his hand and his own money at risk. VAT and tax liabilities were ring fenced, creditors were paid down on agreed terms, and the business was put back on a professional footing.<br /><br />The staff stayed throughout, with natural turnover only.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_2_label', '<strong>The Intervention</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_3_body', 'Twenty four months later the business had moved from insolvency risk to stable, consistent monthly profit.<br /><br />It became saleable, was sold at a profit, and was turned around with no outside investment.<br /><br /><strong>From insolvency risk to a marketable asset.</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.phase_3_label', '<strong>The Result</strong>') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
INSERT INTO content (section_key, content) VALUES ('casestudy__4.subtext', 'A business brought back under control.') ON CONFLICT (section_key) DO UPDATE SET content = EXCLUDED.content;
